"""Exception hierarchy for the append-only key-value store."""

from __future__ import annotations

import pathlib


class KVStoreError(Exception):
    """Base error for store, record, and segment failures."""


class RecordError(KVStoreError):
    """A single record could not be decoded."""


class IncompleteRecordError(RecordError):
    """The buffer ends before the record's declared bytes are present."""


class CorruptRecordError(RecordError):
    """The record bytes are complete but illegal."""


class CorruptSegmentError(KVStoreError):
    """A segment contains a corrupt record at a known offset."""

    def __init__(self, path: pathlib.Path, offset: int, reason: str) -> None:
        self.path = pathlib.Path(path)
        self.offset = offset
        self.reason = reason
        super().__init__(f"{self.path.name}: offset {self.offset}: {self.reason}")

    def __str__(self) -> str:
        return f"{self.path.name}: offset {self.offset}: {self.reason}"

"""Binary codec for KVR1 records."""

from __future__ import annotations

import struct
import zlib

from kvstore.errors import CorruptRecordError, IncompleteRecordError

MAGIC = b"KVR1"
HEADER_SIZE = 15
FLAG_VALUE = 0x00
FLAG_TOMBSTONE = 0x01
_HEADER = struct.Struct(">4sBHII")


def encode_record(key: str, value: str | None) -> bytes:
    """Encode a value record, or a tombstone when value is None."""
    if not isinstance(key, str):
        raise TypeError("key must be str")
    key_bytes = key.encode("utf-8")
    if not 1 <= len(key_bytes) <= 65535:
        raise ValueError("key UTF-8 length must be in 1..65535")
    flags, value_bytes = _value_bytes(value)
    crc = zlib.crc32(key_bytes + value_bytes) & 0xFFFFFFFF
    header = _HEADER.pack(MAGIC, flags, len(key_bytes), len(value_bytes), crc)
    return header + key_bytes + value_bytes


def decode_record(buf: bytes, offset: int = 0) -> tuple[str, str | None, int]:
    """Decode one record starting at offset.

    Length is checked before header validity so a short buffer is always
    incomplete, even when the partial bytes would not form a legal header.
    Structural problems are then reported before the CRC, and the CRC before
    UTF-8 decoding.
    """
    available = len(buf) - offset
    if available < HEADER_SIZE:
        raise IncompleteRecordError("incomplete record header")
    magic, flags, key_len, value_len, crc = _HEADER.unpack_from(buf, offset)
    total = HEADER_SIZE + key_len + value_len
    if available < total:
        raise IncompleteRecordError("incomplete record body")
    _check_structure(magic, flags, key_len, value_len)
    start = offset + HEADER_SIZE
    payload = buf[start:start + key_len + value_len]
    _check_crc(payload, crc)
    return _decode_text(payload, key_len, flags, total)


def _value_bytes(value: str | None) -> tuple[int, bytes]:
    if value is None:
        return FLAG_TOMBSTONE, b""
    if not isinstance(value, str):
        raise TypeError("value must be str or None")
    return FLAG_VALUE, value.encode("utf-8")


def _check_structure(magic: bytes, flags: int, key_len: int, value_len: int) -> None:
    if magic != MAGIC:
        raise CorruptRecordError("bad magic")
    if flags not in (FLAG_VALUE, FLAG_TOMBSTONE):
        raise CorruptRecordError("unknown flags")
    if key_len == 0:
        raise CorruptRecordError("key length is zero")
    if flags == FLAG_TOMBSTONE and value_len != 0:
        raise CorruptRecordError("tombstone with non-zero value_len")


def _check_crc(payload: bytes, expected: int) -> None:
    actual = zlib.crc32(payload) & 0xFFFFFFFF
    if actual != expected:
        raise CorruptRecordError("crc mismatch")


def _decode_text(payload: bytes, key_len: int, flags: int, total: int) -> tuple[str, str | None, int]:
    try:
        key = payload[:key_len].decode("utf-8")
        if flags == FLAG_TOMBSTONE:
            return key, None, total
        value = payload[key_len:].decode("utf-8")
    except UnicodeDecodeError as exc:
        raise CorruptRecordError("invalid utf-8") from exc
    return key, value, total

"""One append-only segment file."""

from __future__ import annotations

import os
import pathlib
from collections.abc import Iterator
from typing import BinaryIO

from kvstore.errors import CorruptRecordError, CorruptSegmentError, IncompleteRecordError
from kvstore.record import decode_record

# A torn tail is left on disk so its bytes still count. The next append to this
# segment truncates back to the last complete record first; otherwise a later
# scan would stop at the tail and miss the new record.


class Segment:
    def __init__(self, path: pathlib.Path, seg_id: int) -> None:
        self._path = pathlib.Path(path)
        self._seg_id = seg_id
        self._fh = self._open()
        self._fh.seek(0, os.SEEK_END)
        self._size = self._fh.tell()
        self._logical: int | None = None

    @property
    def seg_id(self) -> int:
        return self._seg_id

    @property
    def path(self) -> pathlib.Path:
        return self._path

    @property
    def size(self) -> int:
        """Current byte length of the file, including any torn tail."""
        return self._size

    def append(self, blob: bytes) -> int:
        """Append blob and return the offset it was written at."""
        self._discard_torn_tail()
        offset = self._size
        fh = self._require_open()
        fh.seek(offset)
        fh.write(blob)
        fh.flush()
        os.fsync(fh.fileno())
        self._size = offset + len(blob)
        self._logical = self._size
        return offset

    def scan(self) -> Iterator[tuple[str, str | None, int]]:
        """Yield complete records. A torn tail stops the scan; corruption raises."""
        data = self._read_all()
        offset = 0
        limit = len(data)
        while offset < limit:
            try:
                key, value, total = decode_record(data, offset)
            except IncompleteRecordError:
                self._logical = offset
                return
            except CorruptRecordError as exc:
                raise CorruptSegmentError(self._path, offset, str(exc)) from exc
            yield key, value, offset
            offset += total
        self._logical = offset

    def close(self) -> None:
        fh = self._fh
        self._fh = None
        if fh is not None and not fh.closed:
            fh.close()

    def _open(self) -> BinaryIO:
        if self._path.exists():
            return self._path.open("r+b")
        return self._path.open("w+b")

    def _require_open(self) -> BinaryIO:
        if self._fh is None or self._fh.closed:
            raise ValueError("segment is closed")
        return self._fh

    def _read_all(self) -> bytes:
        fh = self._require_open()
        fh.flush()
        fh.seek(0)
        data = fh.read()
        self._size = len(data)
        fh.seek(self._size)
        return data

    def _discard_torn_tail(self) -> None:
        logical = self._logical_end()
        if logical == self._size:
            return
        fh = self._require_open()
        fh.truncate(logical)
        fh.flush()
        self._size = logical
        self._logical = logical

    def _logical_end(self) -> int:
        if self._logical is not None:
            return self._logical
        data = self._read_all()
        self._logical = _logical_end(data)
        return self._logical


def _logical_end(data: bytes) -> int:
    offset = 0
    limit = len(data)
    while offset < limit:
        try:
            _, _, total = decode_record(data, offset)
        except IncompleteRecordError:
            return offset
        except CorruptRecordError:
            return offset
        offset += total
    return offset

"""In-memory key to record-location index."""

from __future__ import annotations

import dataclasses


@dataclasses.dataclass(frozen=True)
class Location:
    seg_id: int
    offset: int


class Index:
    def __init__(self) -> None:
        self._entries: dict[str, tuple[Location, bool]] = {}

    def put(self, key: str, loc: Location, *, tombstone: bool) -> None:
        """Record the newest location for key, replacing any earlier one."""
        self._entries[key] = (loc, tombstone)

    def get(self, key: str) -> Location | None:
        """Return the location of a live key, or None if absent or tombstoned."""
        found = self._entries.get(key)
        if found is None or found[1]:
            return None
        return found[0]

    def live_keys(self) -> list[str]:
        """Live keys ordered by newest-record position (seg_id, offset)."""
        ranked = [
            (loc.seg_id, loc.offset, key)
            for key, (loc, tombstone) in self._entries.items()
            if not tombstone
        ]
        ranked.sort()
        return [key for _, _, key in ranked]

    def tombstone_count(self) -> int:
        """Number of keys whose newest record is a tombstone."""
        return sum(1 for _, tombstone in self._entries.values() if tombstone)

    def __len__(self) -> int:
        """Number of live keys."""
        return sum(1 for _, tombstone in self._entries.values() if not tombstone)

